const norm = (s: string) => s.replace(/\s+/g, ' ').trim();

/** Returns a function that translates a known English phrase into the visitor's language. */
export function useTx() {
  const { lang } = useI18n();
  return useCallback((s: string) => {
    if (lang === 'en') return s;
    return P[norm(s)]?.[lang] ?? P[`${norm(s)} `]?.[lang] ?? s;
  }, [lang]);
}

/** Translate a React child only when it is plain text; elements pass through unchanged. */
export function useTxNode() {
  const tx = useTx();
  return useCallback((n: ReactNode) => (typeof n === 'string' ? tx(n) : n), [tx]);
}

/** Looks a phrase up for a language; returns undefined when there is no translation. */
export function lookupPhrase(lang: string, s: string): string | undefined {
  if (lang === 'en') return undefined;
  const k = norm(s);
  return (P[k] ?? P[`${k} `])?.[lang as 'fr' | 'es' | 'pt'];
}
